import {
  OPTION_DEFINITIONS,
  OPTION_MAP,
  buildHelpText,
  buildUsage,
  getScriptName,
} from './spec.mjs';

export class CliParseError extends Error {
  constructor(scriptName, message) {
    super(message);
    this.name = 'CliParseError';
    this.scriptName = scriptName;
    this.exitCode = 2;
  }
}

export function parseCommandLine(argv = process.argv) {
  const scriptName = getScriptName(argv);
  const tokens = argv.slice(2);
  const values = {};
  const extras = [];
  let positionalOnly = false;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (positionalOnly) {
      extras.push(token);
      continue;
    }

    if (isHelpToken(token)) {
      return { kind: 'help', scriptName };
    }

    if (token === '--') {
      extras.push(token);
      positionalOnly = true;
      continue;
    }

    if (!token.startsWith('-')) {
      extras.push(token);
      continue;
    }

    const { optionToken, inlineValue } = splitOptionToken(token);
    const definition = OPTION_MAP.get(optionToken);

    if (!definition) {
      extras.push(token);
      continue;
    }

    let rawValue = inlineValue;

    if (rawValue === undefined) {
      const nextToken = tokens[index + 1];

      if (
        nextToken === undefined ||
        nextToken === '--' ||
        isRecognizedOptionToken(nextToken)
      ) {
        throw new CliParseError(
          scriptName,
          `argument ${optionToken}: expected one argument`,
        );
      }

      rawValue = nextToken;
      index += 1;
    }

    values[definition.name] =
      definition.type === 'int'
        ? parseIntegerArgument(scriptName, optionToken, rawValue)
        : rawValue;
  }

  const missing = OPTION_DEFINITIONS.filter(
    ({ name, required }) => required && !(name in values),
  ).map(({ name }) => `--${name}`);

  if (missing.length > 0) {
    throw new CliParseError(
      scriptName,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    throw new CliParseError(
      scriptName,
      `unrecognized arguments: ${extras.join(' ')}`,
    );
  }

  return { kind: 'ok', scriptName, values };
}

export function renderHelp(scriptName) {
  return buildHelpText(scriptName);
}

export function renderParserError(error) {
  return `${buildUsage(error.scriptName)}
${error.scriptName}: error: ${error.message}
`;
}

function isHelpToken(token) {
  return token === '-h' || token === '--help';
}

function isRecognizedOptionToken(token) {
  if (!token || !token.startsWith('-')) {
    return false;
  }

  if (isHelpToken(token)) {
    return true;
  }

  const { optionToken } = splitOptionToken(token);
  return OPTION_MAP.has(optionToken);
}

function splitOptionToken(token) {
  const equalsIndex = token.indexOf('=');

  if (equalsIndex === -1) {
    return { optionToken: token, inlineValue: undefined };
  }

  return {
    optionToken: token.slice(0, equalsIndex),
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function parseIntegerArgument(scriptName, optionToken, rawValue) {
  const trimmedValue = rawValue.trim();

  if (!/^[+-]?(?:\d(?:_?\d)*)$/.test(trimmedValue)) {
    throw new CliParseError(
      scriptName,
      `argument ${optionToken}: invalid int value: '${rawValue}'`,
    );
  }

  const normalizedValue = trimmedValue.replaceAll('_', '');
  const numericValue = Number(normalizedValue);

  if (!Number.isSafeInteger(numericValue)) {
    throw new CliParseError(
      scriptName,
      `argument ${optionToken}: invalid int value: '${rawValue}'`,
    );
  }

