import {
  CliParseError,
  parseCommandLine,
  renderHelp,
  renderParserError,
} from '../cli/parser.mjs';
import { buildUint8, buildUint16LE } from '../builders/numeric.mjs';
import { buildSizedUtf8Bytes } from '../builders/text.mjs';
import { formatPythonBytes } from '../format/python_bytes.mjs';

export function buildResults(args) {
  return [
    buildUint8(args.a),
    buildUint16LE(args.b),
    buildUint8(args.c),
    buildSizedUtf8Bytes(args.d),
    buildUint8(args.f),
    buildUint8(args.g),
    buildUint8(args.i),
    buildSizedUtf8Bytes(args.h),
    buildUint8((args.a + args.b + args.c) % 256),
  ];
}

export function execute(argv = process.argv, io = defaultIo()) {
  try {
    const parsed = parseCommandLine(argv);

    if (parsed.kind === 'help') {
      io.stdout.write(renderHelp(parsed.scriptName));
      return 0;
    }

    const output = buildResults(parsed.values)
      .map((buffer) => formatPythonBytes(buffer))
      .join('\n');

    io.stdout.write(`${output}\n`);
    return 0;
  } catch (error) {
    if (error instanceof CliParseError) {
      io.stderr.write(renderParserError(error));
      return error.exitCode;
    }

    throw error;
  }
}

function defaultIo() {
  return {
    stdout: process.stdout,
    stderr: process.stderr,
  };
}

